      mapDisp: { value: disp },
      lightDir: { value: new Vector3(-0.3, -0.8, 1.5).normalize() },
      ambientColor: { value: new Color(0.35, 0.35, 0.35) },
      dispScale: { value: 0 },
      uDispUnit: { value: modelRadius },
      // world units per unit dispScale (smooth path)
      uUseProperDisp: { value: hasProperDisp ? 1 : 0 },
